import{_ as t,o as s,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const h=JSON.parse(`{"title":"Liste d'Auto-Vérification des Contradictions de Paramètres","description":"","frontmatter":{},"headers":[],"relativePath":"fr/97-设定矛盾自查表.md","filePath":"fr/97-设定矛盾自查表.md"}`),n={name:"fr/97-设定矛盾自查表.md"};function o(d,e,a,u,l,c){return s(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="liste-d-auto-verification-des-contradictions-de-parametres" tabindex="-1">Liste d&#39;Auto-Vérification des Contradictions de Paramètres <a class="header-anchor" href="#liste-d-auto-verification-des-contradictions-de-parametres" aria-label="Permalink to &quot;Liste d&#39;Auto-Vérification des Contradictions de Paramètres&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>97</td></tr><tr><td>Module</td><td>Annexes et matériaux de référence</td></tr><tr><td>Mots-clés principaux</td><td>auto-vérification des contradictions, cohérence des paramètres, vérification logique, contrôle qualité, maintenance des paramètres</td></tr></tbody></table><h2 id="i-notes" tabindex="-1">I. Notes <a class="header-anchor" href="#i-notes" aria-label="Permalink to &quot;I. Notes&quot;">​</a></h2><p>La Liste d&#39;Auto-Vérification des Contradictions de Paramètres est l&#39;outil de contrôle qualité du système de paramètres de la Civilisation Symbiotique de l&#39;Ancre, utilisé pour identifier systématiquement les contradictions de paramètres et incohérences logiques possibles lors de la création de nouveaux paramètres, de la révision d&#39;anciens paramètres et de la mise à jour de documents. Cette liste d&#39;auto-vérification est établie sur la base des 14 paramètres fondamentaux et de la liste de contrôle de cohérence définis dans SPEC.md, couvrant tous les modules : vision du monde, système de culture, système social, système juridique, formes de vie, système technologique, ères historiques, interaction transplanaire, etc. Tout nouveau paramètre ou contenu révisé doit passer tous les points de contrôle de cette liste avant d&#39;être officiellement intégré au système de paramètres.</p><h2 id="ii-controles-de-coherence-des-parametres-fondamentaux" tabindex="-1">II. Contrôles de cohérence des paramètres fondamentaux <a class="header-anchor" href="#ii-controles-de-coherence-des-parametres-fondamentaux" aria-label="Permalink to &quot;II. Contrôles de cohérence des paramètres fondamentaux&quot;">​</a></h2><h3 id="_2-1-noms-de-l-univers-et-concepts-fondamentaux" tabindex="-1">2.1 Noms de l&#39;univers et concepts fondamentaux <a class="header-anchor" href="#_2-1-noms-de-l-univers-et-concepts-fondamentaux" aria-label="Permalink to &quot;2.1 Noms de l&#39;univers et concepts fondamentaux&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Point de contrôle</th><th>Contenu du contrôle</th><th>Critère de réussite</th><th>Problèmes courants</th></tr></thead><tbody><tr><td>C01</td><td>Unification du nom de l&#39;univers</td><td>Le texte entier utilise uniformément « Univers Originel Wanling Hengmao » ou l&#39;abréviation « Univers Hengyuan » ; aucun autre nom ne peut être utilisé</td><td>Mélange de noms non standard : « univers », « dix mille mondes », « tous les cieux », etc.</td></tr><tr><td>C02</td><td>Cohérence de la définition de l&#39;Ancre</td><td>L&#39;Ancre est toujours définie comme « un nœud stable du réseau de lois » ; ses attributs essentiels ne peuvent être modifiés</td><td>Décrire l&#39;Ancre comme un objet, un être ou un corps d&#39;énergie</td></tr><tr><td>C03</td><td>Unification du concept de symbiose</td><td>La symbiose signifie toujours « l&#39;évolution commune de différentes vies par une coopération mutuellement bénéfique » ; la déviation de la position anti-prédation n&#39;est pas autorisée</td><td>Décrire la symbiose comme une assimilation, une annexion ou un contrôle</td></tr><tr><td>C04</td><td>Cohérence de la position centrale</td><td>Maintenir toujours le principe de « La réalité comme fondement » ; les paramètres fictifs ne peuvent être présentés comme réels</td><td>Confondre la frontière entre fiction et réalité</td></tr></tbody></table><h3 id="_2-2-coherence-du-systeme-de-culture" tabindex="-1">2.2 Cohérence du système de culture <a class="header-anchor" href="#_2-2-coherence-du-systeme-de-culture" aria-label="Permalink to &quot;2.2 Cohérence du système de culture&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Point de contrôle</th><th>Contenu du contrôle</th><th>Critère de réussite</th><th>Problèmes courants</th></tr></thead><tbody><tr><td>C05</td><td>Cohérence du nombre total de systèmes</td><td>Le nombre total de systèmes de culture d&#39;origine est toujours de trois cents ; il ne peut être augmenté ni diminué</td><td>Expressions vagues : « plus de trois cents », « plusieurs centaines »</td></tr><tr><td>C06</td><td>Cohérence de la classification des systèmes</td><td>Toujours divisée en six grandes catégories (déduction d&#39;origine, cycle de vie, principes juridiques spatiaux, élévation de la conscience, réseau symbiotique, ingénierie appliquée), avec cinquante systèmes par catégorie</td><td>D&#39;autres méthodes de classification ou des nombres de catégories incohérents</td></tr><tr><td>C07</td><td>Cohérence des Trois Fondations d&#39;Origine</td><td>Les trois premiers systèmes sont toujours l&#39;Itération Déductive (001), le Cycle de Vie (002) et la Régulation des Principes Juridiques Spatiaux (003)</td><td>Modifier les numéros ou les noms des trois premiers systèmes</td></tr><tr><td>C08</td><td>Cohérence du paramètre du Fruit Multiplicateur</td><td>Le Fruit Multiplicateur est toujours un « buff de départ », offrant une amplification déductive centuplée, et a fait l&#39;objet d&#39;une application technologique</td><td>Décrire le Fruit Multiplicateur comme un fruit naturel ou comme non technologisé</td></tr><tr><td>C09</td><td>Cohérence des stades de culture</td><td>Les divisions de stades de chaque système restent conformes au document 14 « Division Unifiée des Stades de Culture »</td><td>Inventer des noms de stades contradictoires avec la division unifiée</td></tr><tr><td>C10</td><td>Cohérence de la position anti-prédation</td><td>La culture prédatrice ne peut être décrite comme un système positif ou acceptable</td><td>Défendre ou embellir la culture prédatrice</td></tr></tbody></table><h3 id="_2-3-coherence-sociale-et-juridique" tabindex="-1">2.3 Cohérence sociale et juridique <a class="header-anchor" href="#_2-3-coherence-sociale-et-juridique" aria-label="Permalink to &quot;2.3 Cohérence sociale et juridique&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Point de contrôle</th><th>Contenu du contrôle</th><th>Critère de réussite</th><th>Problèmes courants</th></tr></thead><tbody><tr><td>C11</td><td>Cohérence des typologies de civilisations</td><td>Toujours les Cinq Typologies (Intensif d&#39;Asie de l&#39;Est, Bien-être Nordique, Pluraliste d&#39;Amérique du Nord, Social Continental Européen, Rattrapage en Développement)</td><td>Une sixième typologie apparaît ou les noms des typologies sont modifiés</td></tr><tr><td>C12</td><td>Cohérence du système juridique</td><td>Toujours Constitution + Loi du Travail + Loi sur la protection des consommateurs + cinq lois d&#39;accompagnement (éducation, santé, logement, environnement, antitrust)</td><td>Omission d&#39;une loi ou ajout d&#39;une loi non établie</td></tr><tr><td>C13</td><td>Cohérence de la structure de gouvernance</td><td>Toujours Assemblée Délibérante de l&#39;Ancre (législatif) + Comité Exécutif Symbiotique (exécutif) + Tribunal Symbiotique (judiciaire) + Comité de Supervision de l&#39;Ancre (supervision)</td><td>Modifier les noms des institutions ou la répartition des pouvoirs</td></tr><tr><td>C14</td><td>Cohérence du Mécanisme de contrat lié à la production</td><td>Toujours centré sur « plus de travail, plus de gain » ; la répartition des ressources se fonde sur la contribution</td><td>Décrire le contrat lié à la production comme un égalitarisme ou une distribution selon les besoins</td></tr><tr><td>C15</td><td>Cohérence de la Stratégie d&#39;activation de 20 %</td><td>Toujours activer 20 % des êtres vivants en Puissances Suprêmes du Plan dès la première phase</td><td>Modifier le taux ou l&#39;objectif d&#39;activation</td></tr></tbody></table><h2 id="iii-controles-de-coherence-logique-inter-modules" tabindex="-1">III. Contrôles de cohérence logique inter-modules <a class="header-anchor" href="#iii-controles-de-coherence-logique-inter-modules" aria-label="Permalink to &quot;III. Contrôles de cohérence logique inter-modules&quot;">​</a></h2><h3 id="_3-1-coherence-de-la-ligne-temporelle" tabindex="-1">3.1 Cohérence de la ligne temporelle <a class="header-anchor" href="#_3-1-coherence-de-la-ligne-temporelle" aria-label="Permalink to &quot;3.1 Cohérence de la ligne temporelle&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Point de contrôle</th><th>Contenu du contrôle</th><th>Critère de réussite</th><th>Problèmes courants</th></tr></thead><tbody><tr><td>L01</td><td>Cohérence des dates des événements historiques</td><td>Les dates de tous les événements historiques restent conformes au document 93 « Tableau Maître de la Division des Ères » et aux documents 70-79</td><td>Le même événement a des dates incohérentes dans différents documents</td></tr><tr><td>L02</td><td>Cohérence de la division des ères</td><td>Les noms des ères et les dates de début et de fin restent conformes au document 70 « Tableau Maître de la Division des Ères »</td><td>Des ères non établies apparaissent ou les frontières des ères sont modifiées</td></tr><tr><td>L03</td><td>Cohérence des périodes des personnages</td><td>Les périodes d&#39;activité des personnages clés restent conformes au document 95 « Personnages Clés et Organisations »</td><td>Un personnage apparaît à une époque où il n&#39;existait pas</td></tr><tr><td>L04</td><td>Cohérence des dates des technologies</td><td>Les dates d&#39;invention et de maturation de chaque technologie restent conformes à la chronologie</td><td>Une technologie est utilisée à une époque antérieure à son invention</td></tr></tbody></table><h3 id="_3-2-coherence-du-systeme-technologique" tabindex="-1">3.2 Cohérence du système technologique <a class="header-anchor" href="#_3-2-coherence-du-systeme-technologique" aria-label="Permalink to &quot;3.2 Cohérence du système technologique&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Point de contrôle</th><th>Contenu du contrôle</th><th>Critère de réussite</th><th>Problèmes courants</th></tr></thead><tbody><tr><td>T01</td><td>Cohérence de la technologie du Miroir de Réplication</td><td>Le Miroir de Réplication est toujours « un dispositif de réplication 1:1 ne touchant pas à l&#39;original », avec zéro interférence dans le processus de réplication</td><td>Décrire le Miroir de Réplication comme capable de modifier l&#39;original ou nécessitant un contact avec l&#39;original</td></tr><tr><td>T02</td><td>Cohérence de l&#39;espace isolé</td><td>L&#39;espace isolé est toujours « un espace indépendant totalement séparé de l&#39;extérieur par des barrières de lois »</td><td>Décrire l&#39;espace isolé comme une pièce ordinaire ou un espace virtuel</td></tr><tr><td>T03</td><td>Cohérence des exigences de culture des principes juridiques spatiaux</td><td>Les exigences de culture de chaque technologie spatiale restent conformes au document 13 « Explication détaillée du Système de Régulation des Principes Juridiques Spatiaux »</td><td>Des cultivateurs de faible stade utilisent des technologies exigeant de hauts stades</td></tr><tr><td>T04</td><td>Cohérence des unités d&#39;énergie</td><td>La mesure de l&#39;énergie utilise uniformément l&#39;« unité standard d&#39;énergie » ; aucune autre unité ne peut être utilisée</td><td>Mélange d&#39;unités non standard : « pierres spirituelles », « pièces de cristal », etc.</td></tr></tbody></table><h3 id="_3-3-coherence-des-regles-transplanaires-et-temporelles" tabindex="-1">3.3 Cohérence des règles transplanaires et temporelles <a class="header-anchor" href="#_3-3-coherence-des-regles-transplanaires-et-temporelles" aria-label="Permalink to &quot;3.3 Cohérence des règles transplanaires et temporelles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Point de contrôle</th><th>Contenu du contrôle</th><th>Critère de réussite</th><th>Problèmes courants</th></tr></thead><tbody><tr><td>K01</td><td>Cohérence de « observer d&#39;abord, puis intervenir dans les limites »</td><td>Toutes les opérations de régression temporelle et transplanaires doivent respecter ce principe ; l&#39;étape d&#39;observation ne peut être omise</td><td>Décrire des opérations intervenant directement sans observation</td></tr><tr><td>K02</td><td>Cohérence de la « restitution de connaissances uniquement »</td><td>Le résultat archéologique se limite aux connaissances et informations abstraites ; ni matière, ni énergie, ni forme de vie ne peuvent être restitués</td><td>Décrire l&#39;acte de ramener des artefacts ou des échantillons dans le plan d&#39;origine</td></tr><tr><td>K03</td><td>Cohérence du système de permis de traversée</td><td>Toute traversée de plan doit obtenir un permis du niveau correspondant ; la traversée sans permis n&#39;est pas autorisée</td><td>Décrire des traversées non autorisées</td></tr><tr><td>K04</td><td>Cohérence de la classification des paradoxes temporels</td><td>Les paradoxes sont toujours divisés en quatre catégories — parricide, informationnel, ontologique et événementiel ; aucun ajout ni changement n&#39;est autorisé</td><td>Des types de paradoxes non établis apparaissent</td></tr><tr><td>K05</td><td>Cohérence de la classification des plans</td><td>Les plans sont toujours divisés en cinq grandes catégories (matériel-substantiel, manifestation d&#39;énergie, domination de conscience, lois fragmentées, voisinage d&#39;origine)</td><td>D&#39;autres méthodes de classification apparaissent</td></tr></tbody></table><h3 id="_3-4-coherence-de-la-vie-et-des-races" tabindex="-1">3.4 Cohérence de la vie et des races <a class="header-anchor" href="#_3-4-coherence-de-la-vie-et-des-races" aria-label="Permalink to &quot;3.4 Cohérence de la vie et des races&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Point de contrôle</th><th>Contenu du contrôle</th><th>Critère de réussite</th><th>Problèmes courants</th></tr></thead><tbody><tr><td>S01</td><td>Cohérence de la classification des races</td><td>Les races sont toujours divisées en huit grandes catégories (forme humanoïde, animale, végétale, élémentaire, énergétique, conscientielle, mécanique, hybride)</td><td>D&#39;autres méthodes de classification apparaissent</td></tr><tr><td>S02</td><td>Cohérence du traitement de la Vie Anomale</td><td>La Vie Anomale est toujours traitée selon les trois types de procédures de traitement normalisées</td><td>Décrire des traitements arbitraires hors procédures</td></tr><tr><td>S03</td><td>Cohérence du traitement des Entités Sombres de Remplacement</td><td>Les Entités Sombres de Remplacement sont toujours traitées selon les Directives Éthiques des Deux Âmes et les règles de traitement des quatre branches</td><td>Décrire l&#39;acte d&#39;éliminer simplement une âme</td></tr><tr><td>S04</td><td>Cohérence de l&#39;égalité des Dix Mille Races</td><td>Toutes les races intelligentes sont égales devant la loi ; les paramètres de discrimination raciale ne sont pas autorisés</td><td>Décrire une race comme naturellement inférieure ou destinée à l&#39;esclavage</td></tr></tbody></table><h2 id="iv-controles-du-format-et-des-normes-documentaires" tabindex="-1">IV. Contrôles du format et des normes documentaires <a class="header-anchor" href="#iv-controles-du-format-et-des-normes-documentaires" aria-label="Permalink to &quot;IV. Contrôles du format et des normes documentaires&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Point de contrôle</th><th>Contenu du contrôle</th><th>Critère de réussite</th><th>Problèmes courants</th></tr></thead><tbody><tr><td>F01</td><td>Exactitude du format du nom de fichier</td><td>Le format du nom de fichier est « XX-Titre du document.md », XX étant un numéro à deux chiffres</td><td>Numéro manquant, titre contenant des espaces, extension de fichier erronée</td></tr><tr><td>F02</td><td>Complétude du bloc d&#39;informations du document</td><td>Le début contient un tableau d&#39;informations avec le numéro, le module et les mots-clés essentiels (3-5)</td><td>Bloc manquant ou champs incomplets</td></tr><tr><td>F03</td><td>Nombre suffisant de titres de niveau deux</td><td>Le corps contient au moins 3 sections avec titres de niveau deux</td><td>Moins de 3 titres de niveau deux</td></tr><tr><td>F04</td><td>Utilisation d&#39;éléments structurés</td><td>Des éléments structurés tels que listes et tableaux sont utilisés pour améliorer la lisibilité</td><td>Paragraphes en texte pur, sans listes ni tableaux</td></tr><tr><td>F05</td><td>Existence de la conclusion</td><td>Un paragraphe « Conclusion » existe à la fin</td><td>Conclusion absente</td></tr><tr><td>F06</td><td>Existence des documents associés</td><td>2-3 numéros et noms de documents associés sont listés à la fin</td><td>Documents associés absents ou inexistants</td></tr><tr><td>F07</td><td>Longueur suffisante</td><td>Le corps ne doit pas être inférieur à 800 caractères (hors titres et méta-informations)</td><td>Corps inférieur à 800 caractères</td></tr><tr><td>F08</td><td>Unification de la terminologie</td><td>Des termes standard tels que « Univers Hengyuan », « Ancre » et « Symbiose » sont utilisés</td><td>Terminologie non unifiée ou expressions non standard</td></tr><tr><td>F09</td><td>Pertinence du style d&#39;écriture</td><td>Style sérieux et systématique de document de paramètres, sans expressions familières</td><td>Expressions familières ou relâchées</td></tr><tr><td>F10</td><td>Concordance des numéros avec la liste</td><td>Les numéros et titres des documents sont conformes à la liste complète des 100 documents de SPEC.md</td><td>Numéros ou titres non conformes à la liste</td></tr></tbody></table><h2 id="v-processus-d-auto-verification-et-mode-d-emploi" tabindex="-1">V. Processus d&#39;auto-vérification et mode d&#39;emploi <a class="header-anchor" href="#v-processus-d-auto-verification-et-mode-d-emploi" aria-label="Permalink to &quot;V. Processus d&#39;auto-vérification et mode d&#39;emploi&quot;">​</a></h2><h3 id="_5-1-processus-d-auto-verification-pour-la-creation-de-nouveaux-parametres" tabindex="-1">5.1 Processus d&#39;auto-vérification pour la création de nouveaux paramètres <a class="header-anchor" href="#_5-1-processus-d-auto-verification-pour-la-creation-de-nouveaux-parametres" aria-label="Permalink to &quot;5.1 Processus d&#39;auto-vérification pour la création de nouveaux paramètres&quot;">​</a></h3><ol><li><strong>Auto-vérification préliminaire</strong> : une fois la création achevée, le créateur contrôle point par point contre cette liste et marque les points problématiques.</li><li><strong>Révision et perfectionnement</strong> : réviser les points marqués afin de tout faire passer.</li><li><strong>Relecture croisée</strong> : soumettre à un autre créateur de paramètres pour une relecture croisée, en s&#39;attachant particulièrement à la cohérence inter-modules.</li><li><strong>Approbation du Comité</strong> : les changements majeurs de paramètres doivent être soumis à l&#39;approbation du Comité de Maintenance des Paramètres.</li><li><strong>Mise à jour d&#39;archivage</strong> : après avoir passé tous les contrôles, intégrer officiellement au système de paramètres et mettre à jour les documents d&#39;index associés.</li></ol><h3 id="_5-2-processus-d-auto-verification-pour-la-revision-d-anciens-parametres" tabindex="-1">5.2 Processus d&#39;auto-vérification pour la révision d&#39;anciens paramètres <a class="header-anchor" href="#_5-2-processus-d-auto-verification-pour-la-revision-d-anciens-parametres" aria-label="Permalink to &quot;5.2 Processus d&#39;auto-vérification pour la révision d&#39;anciens paramètres&quot;">​</a></h3><ol><li><strong>Évaluation d&#39;impact</strong> : évaluer les autres documents et modules de paramètres que le contenu révisé peut affecter.</li><li><strong>Contrôles des documents associés</strong> : effectuer des contrôles de cohérence sur tous les documents associés affectés.</li><li><strong>Révision synchronisée</strong> : réviser en synchronisation le contenu affecté dans les documents associés.</li><li><strong>Enregistrement de version</strong> : enregistrer le contenu de la révision et le numéro de version dans le document 99 « Version des Documents et Notes de Maintenance ».</li><li><strong>Avis d&#39;annonce</strong> : les révisions majeures doivent publier un avis de changement à tous les utilisateurs du système de paramètres.</li></ol><h3 id="_5-3-auto-verification-complete-periodique" tabindex="-1">5.3 Auto-vérification complète périodique <a class="header-anchor" href="#_5-3-auto-verification-complete-periodique" aria-label="Permalink to &quot;5.3 Auto-vérification complète périodique&quot;">​</a></h3><p>Le Comité de Maintenance des Paramètres procède chaque trimestre à une auto-vérification complète de la cohérence des paramètres, contrôlant systématiquement l&#39;ensemble des 100 documents afin d&#39;identifier les contradictions de paramètres et incohérences logiques potentielles. Les résultats de l&#39;auto-vérification forment le « Rapport Trimestriel de Cohérence des Paramètres », rendu public à tous les utilisateurs du système de paramètres.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La Liste d&#39;Auto-Vérification des Contradictions de Paramètres est la « constitution de la qualité » du système de paramètres de la Civilisation Symbiotique de l&#39;Ancre. Grâce à des points de contrôle systématisés et organisés en listes, elle garantit que le système de paramètres maintient toujours sa cohérence logique et son unification terminologique au cours de son expansion et de ses révisions continues. Ce qu&#39;un vaste système de paramètres redoute le plus n&#39;est pas le manque de richesse de contenu, mais l&#39;accumulation de contradictions internes et d&#39;incohérences entre ses parties. L&#39;existence de cette liste d&#39;auto-vérification vise précisément à garantir que le système de paramètres de la Civilisation Symbiotique de l&#39;Ancre, tout en conservant son ouverture et sa croissance, possède toujours un fondement de cohérence solide.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>99-文档版本与维护说明 (Version des Documents et Notes de Maintenance)</li><li>90-术语词典 (Le Dictionnaire de Terminologie)</li><li>00-衡元宙宇宙总览 (Heng Yuan Zhou : Vue d&#39;ensemble du Cosmos)</li></ul>',33)])])}const p=t(n,[["render",o]]);export{h as __pageData,p as default};
